#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
unsigned long lastUpdate;
unsigned int number = 0;

void setup() {
  display.setBrightness(7);
  display.showNumberDec(number, false);
  lastUpdate = millis();
}

void loop() {
  unsigned long now = millis();
  while ((unsigned long)(now - lastUpdate) >= 1000UL) {
    lastUpdate += 1000UL;
    number = (number + 1U) % 10000U;
    display.showNumberDec(number, false);
  }
}
